# Generated by build.py from recipe.yml for recipe surl-read-options-from-a-file. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'mail.txt'), "From: ann@example.com`r`nTo: carol@elsewhere.org`r`nSubject: Hello`r`n`r`nHi.`r`n")
[IO.File]::WriteAllText((Join-Path $PWD 'surl.cfg'), "# Options for surl -K surl.cfg, one per line.`n# The dashes are optional, and so is the = between name and value.`ndirectory = site`nuser = alice:secret`nmail-domain = example.com`n--mailbox ann@example.com:secret`n")
[IO.File]::WriteAllText((Join-Path $PWD 'no-url.cfg'), "directory = missing`n")
[IO.File]::WriteAllText((Join-Path $PWD 'with-url.cfg'), "url = http://127.0.0.1:0/`ndirectory = missing`n")
[IO.File]::WriteAllText((Join-Path $PWD 'typo.cfg'), "directroy = site`n")
$server0 = Start-Process surl -ArgumentList '-K', 'surl.cfg', 'http://127.0.0.1:8080/', 'smtp://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s --digest -u alice:secret http://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
